fn global(paths: &Paths, request: &GlobalRequest) -> Result<Global, Error> { let removed = request.removed_context_kinds.as_ref().map(|items|items.iter().map(|x|x.value().to_string()).collect::<Vec<_>>()).unwrap_or_default(); let mut included=Vec::new(); for (kind,reference,why,removable) in [("person",PERSON,"当前本地 owner scope。",false),("page",request.page.value(),"当前可见页面。",true),("domain","work","固定 Work Domain。",true),("context",CONTEXT,"固定 Project-backed Context。",true),("memory_source_refs",paths.mode.source(),"仅引用来源身份，不复制原文。",true)] { if !removed.iter().any(|x|x==kind) { included.push(ContextItem { kind:kind.into(),reference:reference.into(),inclusion_reason:why.into(),authorization:"read_context:granted".into(),evidence_status:"current".into(),removable }); } } if let Some(selection)=request.selection_ref.as_ref() { if !removed.iter().any(|x|x=="selection") { included.push(ContextItem { kind:"selection".into(),reference:selection.clone(),inclusion_reason:"用户显式选中内容身份引用。".into(),authorization:"read_context:granted".into(),evidence_status:"identity_only".into(),removable:true }); } } Ok(Global { context_id:CONTEXT.into(),page:request.page.value().into(),selection_ref:request.selection_ref.clone(),included,removed_context_kinds:removed,authorization_summary:vec!["all_remaining_refs_reauthorized".into()],permissions:vec![if paths.mode==InputMode::Real{"model_port:disabled_for_real_input"}else{"model_port:offline_synthetic_only"}.into()],evidence_status:"current".into(),request_local:true }) }
fn understanding(paths: &Paths, request: &UnderstandingRequest) -> Result<Understanding, Error> { if paths.mode==InputMode::Real { return Ok(Understanding { understanding_id:String::new(),observation:None,suggestion:None,identity:"no_reliable_understanding",processor:"real_model_disabled".into(),processor_version:"p3-133-v1".into(),basis_refs:Vec::new(),why:"真实输入模式不会向 ModelPort、OfflineSyntheticModelAdapter、网络或外部进程提供原文。".into(),evidence_state:"insufficient".into(),synthetic_adapter:false,disclosure:Some(REAL_DISCLOSURE.into()) }); } if request.context_id != CONTEXT || !request.request_id.starts_with("p3-132-") { return Err(Error::blocked("request_id_rejected", "合成 Understanding 请求不符合合同。")); } let _ = request.page; let _ = &request.selection_ref; let _ = &request.removed_context_kinds; Ok(Understanding { understanding_id:"understanding:synthetic:fixed".into(),observation:Some("当前 Context 已具备继续推进所需的已确认 Evidence。".into()),suggestion:Some("继续完成 LifeOS Context Recovery 合成验收记录的复核。".into()),identity:"ai_observation_and_suggestion",processor:"offline_synthetic_model:p3-132-v1".into(),processor_version:"p3-132-v1".into(),basis_refs:Vec::new(),why:"离线固定合成适配器只用于合成验证。".into(),evidence_state:"sufficient".into(),synthetic_adapter:true,disclosure:None }) }
fn feedback(paths: &Paths, request: &FeedbackRequest) -> Result<Feedback, Error> { if paths.mode==InputMode::Real { return Ok(Feedback { status:"unavailable".into(),feedback_id:String::new(),understanding_id:String::new(),decision:request.decision.value().into(),feedback_text:None,audit_event_count:0 }); } let _ = (&request.understanding_id,&request.edited_text,&request.idempotency_key); Err(Error::blocked("understanding_feedback_not_implemented", "本任务不写入合成 Understanding Feedback。")) }
fn status(paths: &Paths) -> Status { Status { status:"ready",offline:true,ai_enabled:paths.mode==InputMode::Synthetic,renderer_direct_capabilities:Vec::new(),ipc_allowlist:IPC.to_vec(),unknown_ipc:"rejected",filesystem:false,raw_database:false,generic_path_api:false,shell:false,process_spawn:false,network:false,vault:false,export:false,sync:false,context_recovery:"project_backed_only",candidate_rule:"explicit_user_decision_required",memory_duplicate_original:false,model_port:if paths.mode==InputMode::Real{"disabled_for_real_input"}else{"offline_synthetic_only"},model_adapter:if paths.mode==InputMode::Real{"disabled_in_real_mode"}else{"offline_synthetic_model:p3-132-v1"} } }

