#[cfg(test)] mod tests { use super::*; use sha2::{Digest,Sha256}; fn test_paths(name:&str)->Paths{let base=paths().unwrap().root;fs::create_dir_all(&base).unwrap();let root=base.join(format!("unit-{name}-{}",now().unwrap()));let _=fs::remove_dir_all(&root);let current=mode().unwrap();if current==InputMode::Synthetic{fs::create_dir(&root).unwrap();}Paths{db:root.join(DB),root,mode:current}} fn clean(p:&Paths){let _=fs::remove_dir_all(&p.root);} fn hash(p:&Path)->String{let mut h=Sha256::new();h.update(fs::read(p).unwrap());format!("{:x}",h.finalize())}
#[test] fn real_preexisting_database_is_rejected_before_write(){if mode().unwrap()!=InputMode::Real{return;}let p=test_paths("real-existing-db");fs::create_dir(&p.root).unwrap();fs::write(&p.db,b"not-a-sqlite-db").unwrap();let before=hash(&p.db);let error=capture(&p,&CaptureRequest{text:"安全测试".into(),key:"p3-133-real-ui-existing-db".into()}).unwrap_err();assert_eq!(error.code,"database_unavailable");assert_eq!(before,hash(&p.db));clean(&p);}
#[test] fn status_is_closed_to_the_frozen_eleven_ipc(){let p=paths().unwrap();let s=status(&p);assert_eq!(s.ipc_allowlist,IPC);assert!(!s.filesystem&&!s.raw_database&&!s.generic_path_api&&!s.shell&&!s.process_spawn&&!s.network&&!s.vault&&!s.export&&!s.sync);if p.mode==InputMode::Real{assert!(!s.ai_enabled);assert_eq!(s.model_port,"disabled_for_real_input");assert_eq!(s.model_adapter,"disabled_in_real_mode");}else{assert!(s.ai_enabled);assert_eq!(s.model_port,"offline_synthetic_only");}}
#[test] fn synthetic_lifecycle_and_no_write_rejection(){if mode().unwrap()==InputMode::Real{return;}let p=test_paths("synthetic");let c=capture(&p,&CaptureRequest{text:SYN_TEXT.into(),key:SYN_KEY.into()}).unwrap();assert_eq!(c.record_count,1);assert!(next(&p,&ContextRequest{context_id:CONTEXT.into()}).unwrap().candidates.is_empty());confirm(&p,&ConfirmRequest{capture_id:c.record.id,context_id:CONTEXT.into(),decision:LinkDecision::Confirm,idempotency_key:"p3-131-link-001".into()}).unwrap();let candidate=next(&p,&ContextRequest{context_id:CONTEXT.into()}).unwrap().candidates.remove(0);decide(&p,&NextRequest{candidate_id:candidate.candidate_id,decision:NextDecision::Accept,edited_text:None,idempotency_key:"p3-131-accept-001".into()}).unwrap();assert_eq!(today(&p).unwrap().confirmed_actions.len(),1);let before=hash(&p.db);assert_eq!(capture(&p,&CaptureRequest{text:"bad".into(),key:"bad".into()}).unwrap_err().code,"argument_schema_rejected");assert_eq!(before,hash(&p.db));clean(&p);}
#[test] fn synthetic_insufficient_evidence_never_creates_candidate_or_action(){if mode().unwrap()==InputMode::Real{return;}let p=test_paths("synthetic-insufficient");let c=capture(&p,&CaptureRequest{text:SYN_SHORT.into(),key:SYN_SHORT_KEY.into()}).unwrap();assert_eq!(c.link_status,"unlinked_insufficient");let before=hash(&p.db);assert!(next(&p,&ContextRequest{context_id:CONTEXT.into()}).unwrap().candidates.is_empty());assert!(today(&p).unwrap().confirmed_actions.is_empty());assert_eq!(before,hash(&p.db));let reopened=read(&p).unwrap();let captures:i64=reopened.query_row("SELECT count(*) FROM captures",[],|r|r.get(0)).unwrap();let candidates:i64=reopened.query_row("SELECT count(*) FROM candidate_actions",[],|r|r.get(0)).unwrap();let actions:i64=reopened.query_row("SELECT count(*) FROM actions",[],|r|r.get(0)).unwrap();assert_eq!((captures,candidates,actions),(1,0,0));clean(&p);}
#[test] fn real_mode_is_limited_and_never_calls_adapter(){if mode().unwrap()!=InputMode::Real{return;}let p=test_paths("real");let marker="P3_133_PRIVATE_TAINT";let max="甲".repeat(200);capture(&p,&CaptureRequest{text:max,key:"p3-133-real-ui-test-first".into()}).unwrap();for i in 1..3{capture(&p,&CaptureRequest{text:format!("{marker}-{i}"),key:format!("p3-133-real-ui-test-{i}")}).unwrap();}let before=hash(&p.db);assert_eq!(capture(&p,&CaptureRequest{text:"乙".repeat(201),key:"p3-133-real-ui-fourth".into()}).unwrap_err().code,"real_input_rejected");assert_eq!(before,hash(&p.db));assert_eq!(capture(&p,&CaptureRequest{text:"fourth".into(),key:"p3-133-real-ui-fourth".into()}).unwrap_err().code,"input_limit_rejected");assert_eq!(before,hash(&p.db));let latest=today(&p).unwrap().records.last().unwrap().id.clone();confirm(&p,&ConfirmRequest{capture_id:latest,context_id:CONTEXT.into(),decision:LinkDecision::Confirm,idempotency_key:"p3-133-real-ui-link-001".into()}).unwrap();let candidate=next(&p,&ContextRequest{context_id:CONTEXT.into()}).unwrap().candidates.remove(0);assert_eq!(candidate.text,REAL_ACTION);let action=decide(&p,&NextRequest{candidate_id:candidate.candidate_id,decision:NextDecision::Accept,edited_text:None,idempotency_key:"p3-133-real-ui-accept-001".into()}).unwrap().action.unwrap();assert!(action.action_id.starts_with("action:p3-133:"));assert_eq!(today(&p).unwrap().confirmed_actions.len(),1);let unavailable=understanding(&p,&UnderstandingRequest{context_id:CONTEXT.into(),page:Page::Today,selection_ref:None,removed_context_kinds:None,request_id:"no-content-read".into()}).unwrap();assert!(!unavailable.synthetic_adapter);assert_eq!(unavailable.disclosure.as_deref(),Some(REAL_DISCLOSURE));let conn=read(&p).unwrap();let audit_text:String=conn.query_row("SELECT group_concat(detail,'|') FROM audit",[],|r|r.get(0)).unwrap();let derived:i64=conn.query_row("SELECT count(*) FROM understandings",[],|r|r.get(0)).unwrap();assert!(!audit_text.contains(marker));assert_eq!(derived,0);assert_eq!(today(&p).unwrap().confirmed_actions[0].action_id,action.action_id);clean(&p);}
}
